package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;import java.io.*;import com.google.gson.*;
public final class SyncChecks {
 public static class Player {UUID id;int entityId;double px;public float yBodyRot,yBodyRotO,yHeadRot,yHeadRotO;Player(int entityId,double x){this.id=UUID.randomUUID();this.entityId=entityId;this.px=x;}public UUID getUUID(){return id;}public int getId(){return entityId;}public double getX(){return px;}public double getY(){return 64;}public double getZ(){return 0;}public Vec getPosition(float part){return new Vec(px,64,0);}public float getYRot(float part){return 0;}public float getXRot(float part){return 0;}public boolean isCrouching(){return false;}}
 public static class Vec {public double x,y,z;Vec(double x,double y,double z){this.x=x;this.y=y;this.z=z;}}
 public static class MC {public Object player,level;MC(Object player){this.player=player;}}
 public static class Buffer {public Object getBuffer(Object layer){return layer;}}
 public static class Sink implements VertexSink {int count;double x;public void vertex(Object c,float x,float y,float z,int color,float u,float v,int overlay,int light,float nx,float ny,float nz){this.count++;this.x+=x;}void reset(){count=0;x=0;}}
 static void require(boolean b,String message){if(!b)throw new AssertionError(message);}
 static SyncCodec.State packet(int[]ids)throws Exception{return SyncCodec.decode(SyncCodec.encode("catalog","0123456789abcdef0123456789abcdef",ids,2,false),"catalog");}
 public static void main(String[]args)throws Exception{Assets.load(Files.readAllBytes(Paths.get(args[0])));Names.loader=SyncChecks.class.getClassLoader();Names.names=new JsonParser().parse(new String(Files.readAllBytes(Paths.get(args[1])),"UTF-8")).getAsJsonObject();for(Assets.Entry e:Assets.entries){e.model=Models.load(e);e.texture=e.layer=new Object();}
  Player local=new Player(1,0),other=new Player(2,10),third=new Player(3,20);Session.mc=new MC(local);CosmeticSync.catalog="catalog";CosmeticSync.visible.put(other.id,other);CosmeticSync.visible.put(third.id,third);long now=System.currentTimeMillis();CosmeticSync.accept(other.id,packet(new int[]{38,35,26,36,16}),now);CosmeticSync.accept(third.id,packet(new int[]{38,22}),now);CosmeticSync.Remote first=CosmeticSync.remotes.get(other.id),second=CosmeticSync.remotes.get(third.id);require(first.equipped.get("companion")!=second.equipped.get("companion"),"Remote follower state shared between players");Assets.Entry entry=first.equipped.get("companion");entry.px=123;CosmeticSync.accept(other.id,packet(new int[]{38,35,26,36,16}),now+1);require(first.equipped.get("companion")==entry&&entry.px==123,"Heartbeat resets follower animation/location");require(Session.equipped.isEmpty(),"Peer packet changes local loadout");boolean rejected=false;try{CosmeticSync.accept(other.id,packet(new int[]{26,27,36}),now);}catch(IOException expected){rejected=true;}require(rejected,"Third flying pet accepted");rejected=false;try{SyncCodec.decode(new byte[2049],"catalog");}catch(Exception expected){rejected=true;}require(rejected,"Oversized packet accepted");rejected=false;try{SyncCodec.decode(SyncCodec.encode("wrong","0123456789abcdef0123456789abcdef",new int[]{38},1,false),"catalog");}catch(Exception expected){rejected=true;}require(rejected,"Version mismatch accepted");
  CosmeticSync.byEntity.put(2,first);CosmeticSync.byEntity.put(3,second);require(CosmeticSync.selectionForEntity(2).get("cloak").id==16&&CosmeticSync.selectionForEntity(3).get("cloak").id==22,"Cape assigned to wrong owner");require(CosmeticSync.selectionForEntity(1).isEmpty(),"Remote cape leaks onto local player");
  Sink sink=new Sink();World.sink=sink;World.buffers=new Buffer();Models.Mat view=new Models.Mat();Map<String,Assets.Entry> onlyA=new LinkedHashMap<String,Assets.Entry>(),onlyB=new LinkedHashMap<String,Assets.Entry>();onlyA.put("companion",first.equipped.get("companion"));onlyB.put("companion",second.equipped.get("companion"));entry.placed=false;World.drawOwner(other,new Object(),onlyA,view,0,64,0,1,false,0);require(sink.count>0,"Remote owner not drawn");double a=sink.x/sink.count;sink.reset();World.drawOwner(third,new Object(),onlyB,view,0,64,0,1,false,0);double b=sink.x/sink.count;require(b-a>8,"Remote geometry is drawn on wrong player");require(World.motions.size()==2,"Owner motion states shared");SyncCodec.State clear=packet(new int[0]);clear.clear=true;CosmeticSync.accept(other.id,clear,now+2);require(!CosmeticSync.remotes.containsKey(other.id),"Disconnect does not clear appearance");System.out.println("PASS real remote model rendering on separate owners, isolated followers, heartbeat continuity, cloak ownership, packet bounds/version checks, two-fly limit and disconnect clearing");}
}
